#!/usr/bin/env bash
#
# A QA wizard walks a developer through every acceptance criterion of one
# feature, one stage at a time: open the page, do the steps, record pass or fail.
# Generated by /speckit.qa.walk from extensions/qa/scripts/qa-wizard.sh.
# Adapted from Matt Pocock's `wizard` skill (github.com/mattpocock/skills), MIT.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-check stages below the marker.
#
# Usage: ./qa-walk.sh [--only US1-2,EC-1] [--no-browser] [--reopen] [--results <path>]
#   --only       walk only these stage ids; other rows in the results file are kept
#   --no-browser print each URL instead of opening it
#   --reopen     open every URL again, even one already opened this run
#   --results    where the markdown results table goes (default: beside this script)

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

ONLY=""
NO_BROWSER="${NO_BROWSER:-}"
REOPEN=""
RESULTS=""

while [[ $# -gt 0 ]]; do
  case "$1" in
    # A bare --only eats the next option as its value, so the filter matches no
    # stage and the walk reports success having checked nothing.
    --only)
      [[ $# -ge 2 && "$2" != --* ]] ||
        { printf '%s\n' '--only needs a stage list' >&2; exit 2; }
      ONLY="$2"; shift 2 ;;
    --only=*)     ONLY="${1#*=}"; shift ;;
    --no-browser) NO_BROWSER=1; shift ;;
    --reopen)     REOPEN=1; shift ;;
    --results)
      [[ $# -ge 2 && "$2" != --* ]] ||
        { printf '%s\n' '--results needs a path' >&2; exit 2; }
      RESULTS="$2"; shift 2 ;;
    --results=*)  RESULTS="${1#*=}"; shift ;;
    -h|--help)    sed -n '11,15p' "${BASH_SOURCE[0]}"; exit 0 ;;
    *) printf 'unknown option: %s\n' "$1" >&2; exit 2 ;;
  esac
done

# The last entry of BASH_SOURCE is the wizard itself, whether this library was
# copied into it or sourced from beside it, so the results land by the wizard.
_WIZARD="${BASH_SOURCE[$((${#BASH_SOURCE[@]} - 1))]}"
RESULTS="${RESULTS:-$(cd "$(dirname "$_WIZARD")" && pwd)/qa-walk-results.md}"

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
_STAGE_ID=""
_SKIPPING=""      # non-empty while --only excludes the current stage
RECORDS=()        # one tab-separated record per check: id, check, result, note
_SEEN=()          # every stage id this wizard declares, for the --only check
_OPENED=()        # every URL opened this run, so none is opened twice

# _clear wipes the terminal so only the current stage is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# _excluded ID succeeds when --only was given and does not name ID.
_excluded() {
  [[ -n "$ONLY" ]] || return 1
  [[ ",$ONLY," != *",$1,"* ]]
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser. This wizard tells you what to open and what to look\n' "$DIM"
  printf '  for, then records pass, fail or skip for each check. Stop any time with\n'
  printf '  Ctrl-C. Re-run with --only <id,...> to walk only the stages you name.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage ID "Title" clears the screen, announces the stage and shows progress.
# The id is the spec's own (US1-2, EC-1, SC-003) so results trace back to it.
stage() {
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  _STAGE_ID="$1"
  _SEEN+=("$1")
  if _excluded "$1"; then _SKIPPING=1; return 0; fi
  _SKIPPING=""
  _clear
  printf '\n%s%s▸ Stage %s/%s · %s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$2" "$RESET"
}

# say "..." prints the Given: the state the check starts from.
say()  { [[ -n "$_SKIPPING" ]] || printf '  %s\n' "$1"; }
# step "..." is one action the developer takes: the When.
step() { [[ -n "$_SKIPPING" ]] || printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { [[ -n "$_SKIPPING" ]] || printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { [[ -n "$_SKIPPING" ]] || printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }
good() { [[ -n "$_SKIPPING" ]] || printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# open_url URL opens it in the developer's browser, cross-platform incl. WSL.
open_url() {
  [[ -n "$_SKIPPING" ]] && return 0
  local url="$1"
  if [[ -n "$NO_BROWSER" ]]; then
    printf '  %s↗ open%s %s\n' "$GREEN" "$RESET" "$url"; return 0
  fi
  # A walk returns to the same page many times: one wizard opens 5 pages across
  # 35 calls. Opening each time buries the reviewer in duplicate tabs, so a URL
  # already opened this run is named instead. --reopen restores every open.
  if [[ -z "$REOPEN" ]]; then
    local opened=" ${_OPENED[*]-} "
    if [[ "$opened" == *" $url "* ]]; then
      printf '  %s↗ already open%s %s\n' "$DIM" "$RESET" "$url"
      return 0
    fi
  fi
  _OPENED+=("$url")
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview      >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open     >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open         >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the developer to finish the manual part.
pause() {
  [[ -n "$_SKIPPING" ]] && return 0
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes. Put it before any
# step that changes data.
confirm() {
  [[ -n "$_SKIPPING" ]] && return 1
  local reply=""
  printf '  %s? %s [y/N]%s ' "$YELLOW" "$1" "$RESET"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# check "expected" states the Then and records pass, fail or skip for the
# current stage. Every verdict takes a one-line note; a skip asks again until
# it has a reason. q saves the rows so far and ends the walk.
check() {
  [[ -n "$_SKIPPING" ]] && return 0
  printf '  %s✔ Expected:%s %s\n' "$BOLD" "$RESET" "$1"
  local verdict="" reply="" note_text="" colour=""
  while [[ -z "$verdict" ]]; do
    printf '  %s? pass / fail / skip / quit [p/f/s/q]%s ' "$YELLOW" "$RESET"
    # End of input records a skip, so a piped run never spins.
    if ! read -r reply; then verdict="skip"; break; fi
    case "${reply//[[:space:]]/}" in
      [pP]*) verdict="pass" ;;
      [fF]*) verdict="fail" ;;
      [sS]*) verdict="skip" ;;
      [qQ]*) finish; exit 0 ;;
    esac
  done
  local label="Note (optional):"
  [[ "$verdict" == "skip" ]] && label="Why skipped:"
  while :; do
    printf '  %s%s%s ' "$BOLD" "$label" "$RESET"
    read -r note_text || { note_text=""; break; }   # end of input keeps an empty reason
    [[ "$verdict" != "skip" || -n "${note_text//[[:space:]]/}" ]] && break
  done
  case "$verdict" in
    pass) colour="$GREEN" ;;
    fail) colour="$RED" ;;
    *)    colour="$YELLOW" ;;
  esac
  printf '  %s%s%s\n' "$colour" "$verdict" "$RESET"
  RECORDS+=("$(printf '%s\t%s\t%s\t%s' "$_STAGE_ID" "$1" "$verdict" "$note_text")")
}

# finish clears, writes the results table and shows the closing summary. On an
# --only run, rows for stages not walked this time are kept from the previous
# file. Exit code is 1 when any check failed.
finish() {
  local rows=() line id record r_id r_check r_result r_note
  local pass=0 fail=0 skip=0

  # An id that names no stage silently filters every stage out, and the walk
  # then reports success having checked nothing. Refuse before the results file
  # is written, so a mistyped id never overwrites the rows of a good run.
  if [[ -n "$ONLY" ]]; then
    # Join under the default IFS, because ${_SEEN[*]} separates on the first
    # character of IFS and the split below needs IFS to be a comma.
    local seen=" ${_SEEN[*]-} "
    local -a missing=()
    local want
    local IFS=,
    for want in $ONLY; do
      [[ "$seen" == *" $want "* ]] || missing+=("$want")
    done
    unset IFS
    if [[ ${#missing[@]} -gt 0 ]]; then
      printf '%s\n' "no stage in this wizard is named: ${missing[*]}" >&2
      exit 2
    fi
  fi

  if [[ -n "$ONLY" && -f "$RESULTS" ]]; then
    while IFS= read -r line; do
      [[ "$line" == '| '* ]] || continue
      id="${line#| }"; id="${id%% |*}"
      [[ "$id" == "Id" || "$id" == "---" ]] && continue
      _excluded "$id" && rows+=("$line")
    done < "$RESULTS"
  fi

  for record in ${RECORDS[@]+"${RECORDS[@]}"}; do
    IFS=$'\t' read -r r_id r_check r_result r_note <<< "$record"
    rows+=("| $r_id | ${r_check//|/\\|} | $r_result | ${r_note//|/\\|} |")
  done

  for line in ${rows[@]+"${rows[@]}"}; do
    case "$line" in
      *"| pass |"*) pass=$((pass + 1)) ;;
      *"| fail |"*) fail=$((fail + 1)) ;;
      *"| skip |"*) skip=$((skip + 1)) ;;
    esac
  done

  local walk_note=""
  printf '  %sNote for the whole walk (optional):%s ' "$BOLD" "$RESET"
  read -r walk_note || true

  {
    printf '# QA walk results\n\n'
    printf -- '- **Run**: %s\n' "$(date '+%Y-%m-%d %H:%M')"
    printf -- '- **Result**: %s pass, %s fail, %s skip\n' "$pass" "$fail" "$skip"
    [[ -n "${walk_note//[[:space:]]/}" ]] && printf -- '- **Note**: %s\n' "$walk_note"
    printf '\n'
    printf '| Id | Check | Result | Note |\n|---|---|---|---|\n'
    for line in ${rows[@]+"${rows[@]}"}; do printf '%s\n' "$line"; done
  } > "$RESULTS"

  _clear
  printf '\n'
  if [[ "$fail" -gt 0 ]]; then
    printf '%s%s  ✗ %s check(s) failed%s\n' "$BOLD" "$RED" "$fail" "$RESET"
  else
    printf '%s%s  ✓ Walk complete%s\n' "$BOLD" "$GREEN" "$RESET"
  fi
  printf '%s  %s pass, %s fail, %s skip · written to %s%s\n' \
    "$DIM" "$pass" "$fail" "$skip" "$RESULTS" "$RESET"
  for record in ${RECORDS[@]+"${RECORDS[@]}"}; do
    IFS=$'\t' read -r r_id r_check r_result r_note <<< "$record"
    [[ "$r_result" == "pass" ]] && continue
    printf '  %s- %s %s: %s%s\n' "$DIM" "$r_id" "$r_result" "$r_note" "$RESET"
  done
  printf '\n'
  [[ "$fail" -gt 0 ]] && exit 1
  return 0
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage per check, in the confirmed order.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=33

BASE="${KCC_BASE_URL:-https://localhost:58671}"

# Console snippets, pasted into devtools on the page under test.
JS_FRESH="document.cookie='kcc-visit=; max-age=0; path=/'; location.reload()"
JS_COOKIE="document.cookie.match(/kcc-visit=[^;]+/)[0]"
JS_BACK() {
  printf "document.cookie='kcc-visit=1.'+document.cookie.match(/kcc-visit=1\\\\.([0-9a-f]+)/)[1]+'.'+(Math.floor(Date.now()/1000)-%s)+'; max-age=1800; path=/; secure; samesite=lax'; location.reload()" "$1"
}
JS_STATES="document.getAnimations().filter(a=>a.effect.target?.matches?.('.kcc-wash')).map(a=>a.playState)"
JS_OPACITY="[...document.querySelectorAll('.kcc-wash')].map(w=>getComputedStyle(w).opacity)"
JS_COUNTS="[...document.querySelectorAll('.kcc-washes')].map(f=>f.children.length)"
JS_AT="[...document.querySelectorAll('.kcc-wash')].map(w=>parseFloat(getComputedStyle(w).getPropertyValue('--wash-at'))).sort((a,b)=>a-b)"
JS_SIGS="(s=>[s.length,new Set(s).size])([...document.querySelectorAll('.kcc-washes')].map(f=>[...f.children].map(w=>w.getAttribute('style')).join('|')))"
JS_INKS="[...new Set([...document.querySelectorAll('.kcc-wash')].flatMap(w=>[w.style.getPropertyValue('--wash-ink'),w.style.getPropertyValue('--wash-ink-2')].filter(Boolean)))]"

visit_at() {
  step "Open devtools Console on this page and run:"
  note "  $(JS_BACK "$1")"
  note "  (back-dates the visit start by $1 s; the page reloads)"
}

banner "QA walk: Ink wash bloom and the grain rule"

note "Prerequisites: site running at $BASE (set KCC_BASE_URL to change it). The library needs recipes:"
note "POST $BASE/api/dev/seed-recipes in Development seeds 25 of them. Check both ramps: the ramp"
note "toggle sets data-theme on <html>. Use a normal (non-private) window, with devtools open."
pause "Press Enter to begin."

# ── Page: fresh visit ──────────────────────────────────────────────────────
stage "US1-1" "A fresh visit starts bare"
say "Given no kcc-visit cookie (last visit over 30 minutes ago)."
open_url "$BASE/"
step "In devtools Console run: $JS_FRESH"
step "After the reload run: $JS_COOKIE   (expect kcc-visit=1.<8 hex>.<unix start>)"
step "Run: $JS_OPACITY"
check "No sheet carries a wash: every wash has opacity 0 (or within a hair of it), and none is visible on the page."

stage "SC-001" "100% of sheets bare at the first page of a new visit"
say "Same fresh visit as the stage before; now look at several pages."
open_url "$BASE/recipes"
step "Straight after clearing the cookie, load /recipes, a recipe from it, /account/login and /error/404 (each in turn, within a few seconds)."
step "On each run: $JS_OPACITY"
check "At the first page of a new visit, 100% of sheets carry no visible wash."

stage "US1-2" "Washes arrive one at a time, irregularly, each over about 90 s"
say "Given the library open in a fresh visit."
open_url "$BASE/recipes"
step "Clear the cookie and reload (run: $JS_FRESH)."
step "Run: $JS_AT"
step "Look at the gaps between consecutive values, and keep the page open for a minute or two while watching the sheets."
step "Run: document.getAnimations().filter(a=>a.effect.target?.matches?.('.kcc-wash')).map(a=>a.effect.getComputedTiming().duration)"
check "Washes arrive one at a time at irregular intervals, each spreading over about a minute and a half, never several at once."

stage "US1-3" "A page opened two minutes in arrives with its earned washes"
say "Given a reader two minutes into a visit."
open_url "$BASE/recipes"
visit_at 120
step "Run: document.documentElement.style.getPropertyValue('--wash-elapsed')   (expect about 120s)"
step "Run: $JS_AT   (values under about 30 s are fully bloomed, the later ones partly or not yet)"
step "Click a recipe card to open another page, then run the same two commands."
check "That page arrives with the washes two minutes of visit time have earned, already in place on first paint, and keeps blooming from there."

stage "US1-6" "The same page wears the same arrangement twice in one visit"
say "Given the visit from the stage before, still open."
step "On /recipes run: JSON.stringify([...document.querySelectorAll('.kcc-wash')].map(w=>w.getAttribute('style')))  and note the length and the first 200 characters."
step "Open another page, come back to /recipes (and reload it once), and run the same command."
check "It wears the same arrangement both times."

stage "US1-4" "At five minutes every wash is fully bloomed"
say "Given a reader five minutes or more into a visit."
open_url "$BASE/recipes"
visit_at 300
step "Run: $JS_STATES"
step "Repeat on /, a recipe page, /account/login and /error/404."
check "Every wash on every page is fully bloomed (every playState is \"finished\")."

stage "SC-002" "No wash starts later than 3:30; all bloomed at 5:00"
say "Given the visit at 300 s."
step "Run: Math.max(...$JS_AT)   (use the console on /recipes)"
step "Run: $JS_STATES"
check "At 5 minutes of visit time, 100% of washes on any page are fully bloomed; no wash starts later than 3 minutes 30 seconds (210 s)."

stage "US1-5" "A returning reader after 30 minutes starts again"
say "Given a reader who returns after more than 30 minutes away."
open_url "$BASE/recipes"
step "Note the seed: $JS_COOKIE"
step "Simulate the 30-minute expiry by deleting the cookie, then reload (run: $JS_FRESH)."
step "Compare the new seed with the old one, run $JS_OPACITY, then fast-forward to 300 s and compare the wash arrangement with the earlier visit's."
warn "A real expiry means leaving every site tab closed for 30 minutes; the cookie's Max-Age is 1800, so deleting it is the same state."
check "The visit starts again: the page is bare and the new visit's arrangement differs from the last."

stage "EC-5" "Several tabs share one visit"
say "Given one browser with two tabs on the site."
open_url "$BASE/recipes"
step "Open a second tab on $BASE/ in the same window and compare $JS_COOKIE in both, and --wash-elapsed on <html> in both."
step "In tab 1 run the 120 s back-date (run: $(JS_BACK 120)), then reload tab 2."
check "The tabs share one visit, so pages opened in either tab agree on the visit clock and the arrangement."

stage "EC-4" "A page left open for hours stops changing"
say "Given the library at 300 s."
open_url "$BASE/recipes"
visit_at 300
step "Leave the tab open for a few minutes (a longer wait only repeats this). Then run: $JS_STATES  and  document.getAnimations().filter(a=>a.playState==='running').length"
check "The bloom stops at full; nothing keeps changing (no wash running, no page change)."

stage "EC-1" "Scripts disabled: first paint already earns its washes"
say "Given a visit at 120 s."
open_url "$BASE/recipes"
visit_at 120
step "Open the devtools command menu (Cmd+Shift+P), run 'Disable JavaScript', then reload."
step "Watch the page for a minute."
check "The first paint already shows the washes the visit has earned, and the bloom continues without any script."
note "Re-enable JavaScript afterwards (command menu: 'Enable JavaScript')."

stage "SC-008" "No pop or jump when the page becomes interactive"
say "Given a visit at 120 s, so several washes are mid-bloom."
open_url "$BASE/recipes"
visit_at 120
step "Devtools Performance panel: record a reload, stop, and look at the filmstrip around hydration."
step "Also reload several times with Network throttled to Slow 4G."
check "A page opened mid-visit shows its earned washes on first paint, with no visible pop or jump when the page becomes interactive."

# ── Page: library at full bloom ────────────────────────────────────────────
stage "US2-1" "No two sheets share an arrangement"
say "Given the library at full bloom (300 s)."
open_url "$BASE/recipes"
visit_at 300
step "Run: $JS_SIGS   (prints [sheets with washes, distinct arrangements])"
step "Look over the sheets by eye."
check "No two sheets share the same set of wash positions, sizes and colours (both numbers in the printout are equal)."

stage "SC-004" "Six or more sheets: all different, none over four washes"
say "Given a page with at least six sheets at full bloom (the library)."
step "Run: $JS_SIGS"
step "Run: Math.max(...$JS_COUNTS)"
check "No two sheets share an arrangement, and no sheet carries more than four washes."

stage "US2-2" "Wash count follows sheet size"
say "Given sheets of different sizes at full bloom."
step "Run: $JS_COUNTS   and compare with the sheets on screen (small recipe card, reading sheets, hero or wide sheets)."
check "A small card carries one or two washes, a reading sheet about three, and the largest sheets four, never more than four."

stage "US2-3" "Colours are the eight brand washes, unblended"
say "Given any page at full bloom."
step "Run: $JS_INKS"
step "Compare with the eight wash colours in docs/brand/loose-leaf.md (the --color-* wash tokens)."
step "Zoom in on overlaps; look for any colour that is a blend between two."
check "Every wash is one or two of the eight brand wash colours, used as they are, never a colour blended between them."

stage "SC-005" "Every sampled wash declares a brand wash ink"
say "Given three pages at 300 s: /recipes, a recipe and /."
step "On each, run: $JS_INKS"
check "Every wash on every sampled page declares its ink as one of the eight brand wash colours."

stage "US2-5" "Neighbouring sheets do not bloom in step"
say "Given the library at 120 s so washes are mid-bloom."
visit_at 120
step "Run: [...document.querySelectorAll('.kcc-washes')].map(f=>[...f.children].map(w=>getComputedStyle(w).getPropertyValue('--wash-at')))"
step "Compare adjacent grid cards, and watch them for a minute."
check "Their washes do not arrive at the same moments."

stage "US2-4" "A chosen colour is a sheet's first wash"
say "Given recipe cards, a recipe hero, and a Home card with a backoffice wash colour."
open_url "$BASE/recipes"
step "At 300 s, inspect a recipe card: its first .kcc-wash (data-wash, lowest --wash-at) should wear the recipe's tile colour (--wash-ink)."
open_url "$BASE/"
step "On Home, the same for a Home card whose backoffice wash is set (its first wash wears it; later washes pick freely)."
step "Open a recipe from the library and check the hero the same way."
check "The first wash wears the chosen colour; the sheet's later washes pick freely."

stage "EC-8" "A very small sheet still blooms within its share"
say "Given a pill-sized or small card at 300 s."
step "Find the smallest sheet on /recipes or the pad cards: run $JS_COUNTS and match against that sheet."
check "It carries at most its size's share of washes, and at least one when it blooms at all."

stage "EC-2" "Text over a wash stays legible"
say "Given the library at 300 s, both ramps."
step "Look for washes lying under running text, labels and controls; zoom in on where two overlap."
step "Toggle the ramp and repeat."
check "Washes overlap at most two deep, and ink, soft ink and control hairlines stay clearly readable in both ramps."
note "AA and 3:1 are proved numerically by contrast.test.ts; this is the eyeball pass."

stage "EC-6" "Switching ramps mid-visit keeps arrangement and progress"
say "Given a visit at 120 s with washes mid-bloom."
visit_at 120
step "Note the washes and how far each has bloomed, then switch the ramp (light to dark and back)."
check "Washes keep their arrangement and progress; only the blend changes, as it does today."

stage "FR-018" "Pigment holds in both ramps"
say "Given the library at 300 s."
step "Compare the washes in light (multiply) and dark (screen)."
check "Washes keep their pigment in both ramps; only the blend with the paper differs, as today."

# ── Page: grain rule ───────────────────────────────────────────────────────
stage "US3-1" "Paper and controls are clean"
say "Given the library at 300 s."
open_url "$BASE/recipes"
step "Zoom to 300-400% on bare paper, body text, an input, a button, a label, tape, a status well and a blank sheet beneath a slip."
step "Repeat in the other ramp, and on /account/login."
check "No grain or crayon texture lies over any of them, in either ramp."

stage "US3-2" "The desk keeps its grain"
say "Given any page, both ramps."
step "Zoom on the desk between and around sheets; compare with main's desk if you have it running."
check "The desk shows the same grain and crayon tooth it shows today."

stage "US3-3" "Washes and tiles keep their grain"
say "Given the library at 300 s."
step "Zoom on a wash and on a coloured recipe tile."
check "Each keeps its grain."

stage "US3-4" "The brand documents state the rule"
say "Given docs/brand/loose-leaf.md and docs/brand/kit.md in the repository."
step "Read the Paper rule and Wax paragraphs and the Washes section in both files, and search for 'one wash per sheet' and 'never under running text'."
check "They state the rule: grain on the desk, the washes and the tiles only, and no line contradicts the bloom or the rule."

stage "SC-007" "Zero grain layers outside desk, washes, tiles"
say "Given both ramps."
step "In each ramp inspect with devtools (Layers, or toggle .kcc-grain and .kcc-crayon off) paper, text, controls, labels, tape, wells and blanks."
check "Zero grain or crayon layers lie over paper, text, controls, labels, tape, wells or blank sheets; the desk, washes and tiles keep theirs."

# ── Page: phone menu ───────────────────────────────────────────────────────
stage "EC-3" "A scrolling sheet keeps its washes with its content"
say "Given a phone-width window (375 px) at 300 s."
open_url "$BASE/"
step "Devtools device toolbar at 375 px, open the pad menu (its cards scroll inside themselves)."
step "Scroll the card's content."
check "Its washes stay with its content as it scrolls, and neither the card nor the page gains scroll range."

# ── Reduced motion ─────────────────────────────────────────────────────────
stage "US4-1" "Reduced motion fades without growing"
say "Given reduced motion emulated (devtools Rendering, prefers-reduced-motion: reduce)."
open_url "$BASE/recipes"
step "Enable the emulation, then back-date to 60 s (run: $(JS_BACK 60))."
step "While a wash arrives run: [...document.querySelectorAll('.kcc-wash')].map(w=>[getComputedStyle(w).opacity,getComputedStyle(w).scale])"
check "A wash fades in at its final size and place (scale stays 1; only opacity changes)."

stage "US4-2" "Reduced motion reaches full bloom at five minutes"
say "Given reduced motion still emulated."
visit_at 300
step "Run: $JS_STATES"
check "The page is fully bloomed, the same as for every other reader."

# ── Performance ────────────────────────────────────────────────────────────
stage "SC-009" "Scrolling a fully bloomed page is smooth"
say "Given the library, mobile emulation and 4x CPU throttle."
open_url "$BASE/recipes"
step "At 150 s (the busiest moment) then at 300 s, record the Performance panel while scrolling the page for 5 seconds."
check "No dropped-frame stutter you notice; no long frames, none over 50 ms."

stage "EC-7" "Printing a page"
say "Out of scope per the spec: the page prints with whatever the screen shows."
warn "Nothing to verify; record skip."
check "Out of scope: the page prints with whatever the screen shows."

finish
